<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Pesan untuk Penjual — Rembang UMKM</title><link rel="icon" href="<?= base_url('assets/favicon.ico?v=1') ?>"><link rel="stylesheet" href="<?= base_url('assets/tabler.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/marketplace.css?v=4') ?>"></head><body class="shop-body"><?php $this->load->view('market/_header'); ?><main class="shop-main container-xl"><div class="shop-contact-wrap"><span class="shop-eyebrow">HUBUNGI PENJUAL</span><h1>Pesan sudah disiapkan</h1><p>Rincian pilihan Anda untuk <strong><?= html_escape($intent['store_name']) ?></strong> sudah dirangkum. Periksa pesannya sebelum melanjutkan.</p><div class="shop-message-preview"><div><span>Pesan WhatsApp</span><small><?= html_escape($intent['reference_no']) ?></small></div><textarea id="contact-message" readonly rows="8"><?= html_escape($intent['message_text']) ?></textarea></div><?php if (!$intent['is_demo'] || $test_destination_available): ?><form method="post" action="<?= site_url('kontak/'.$intent['reference_no'].'/buka') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><button class="shop-primary-button" type="submit">Buka WhatsApp <span aria-hidden="true">↗</span></button></form><?php else: ?><button class="shop-primary-button" type="button" id="copy-contact">Salin pesan <span aria-hidden="true">↗</span></button><p class="shop-contact-help">Pesan dapat disalin. Kontak toko akan tersedia setelah nomor penjual dihubungkan.</p><?php endif; ?><a class="shop-contact-back" href="<?= site_url($intent['contact_mode']==='cart_per_store'?'keranjang':'toko/'.$intent['store_slug']) ?>">← Kembali</a></div></main><?php $active_tab='cart';$this->load->view('market/_bottom_nav', array('active_tab' => $active_tab, 'cart_count' => $cart_count)); ?><script>const copyButton=document.getElementById('copy-contact');if(copyButton){copyButton.addEventListener('click',async()=>{const field=document.getElementById('contact-message');try{await navigator.clipboard.writeText(field.value);copyButton.textContent='Pesan tersalin ✓'}catch(error){field.select();document.execCommand('copy');copyButton.textContent='Pesan tersalin ✓'}})}</script></body></html>
